static int ocp_read_byte(struct r8152 *tp, u16 type, u16 index, u32 *value)
{
	u8 shift = index & 3;
	__le32 tmp;
	u32 data;
	int ret;

	index &= ~3;

	ret = generic_ocp_read(tp, index, sizeof(tmp), &tmp, type);
	WARN_ON_ONCE(ret != sizeof(tmp));

	data = __le32_to_cpu(tmp);
	data >>= (shift * 8);
	data &= 0xff;

	*value = (u8)data;

	return ret;
}
